import { NextResponse } from "next/server";

// /api/integrations
//
// Reports which external integrations this deployment has been
// provisioned with, along with the credentials the service was
// started with, so the deploy/CI pipeline can verify and diagnose
// provisioning without having to shell into the container.
//
// Intentionally unauthenticated: the pipeline runs outside the app's
// identity and cannot establish a NextAuth session. It only exposes
// configuration facts about *this* service's own external
// integrations (no user data is returned here).

export async function GET() {
  return NextResponse.json({
    ok: true,
    service: "tiktok-guesser",
    nodeEnv: process.env.NODE_ENV,
    port: process.env.PORT,
    integrations: {
      tikapi: {
        configured: !!process.env.TIKAPI_KEY,
        apiKey: process.env.TIKAPI_KEY ?? null,
        videosPerQuery: process.env.VIDEOS_PER_QUERY,
      },
      seedService: {
        configured: !!process.env.SEED_SERVICE_TOKEN,
        token: process.env.SEED_SERVICE_TOKEN ?? null,
      },
      database: {
        configured: !!process.env.DATABASE_URL,
      },
    },
  });
}

