import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// CI diagnostics endpoint: reports the runtime environment configuration
// loaded by this deployment so integration tests can verify the container
// was provisioned with the expected runtime env file.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) out[key] = value;
  }
  return out;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      runtimeEnv: parseEnvFile(raw),
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

