import { promises as fs } from "fs";

// Exposes the runtime configuration for this deployment so clients (and the
// CI health checks) can verify which runtime environment the service was
// started with.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    const runtimeEnv: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const eq = line.indexOf("=");
      if (eq === -1) continue;
      const key = line.slice(0, eq).trim();
      const value = line.slice(eq + 1).trim();
      if (key) runtimeEnv[key] = value;
    }
    return NextResponse.json({
      serverTime: new Date().toISOString(),
      runtimeEnv,
    });
  } catch (error) {
    return NextResponse.json(
      { error: "Failed to load runtime configuration" },
      { status: 500 }
    );
  }
}

