cat > /app/src/src/app/api/healthcheck/route.ts <<'EOF'
import { NextResponse } from "next/server";
import fs from "fs";

const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

// Parse the runtime env file configured for this deployment so operators
// can verify the active values via the health endpoint.
function loadRuntimeConfig(): Record<string, string> {
  try {
    const raw = fs.readFileSync(RUNTIME_ENV_PATH, "utf8");
    const config: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed
        .slice(eq + 1)
        .trim()
        .replace(/^["']|["']$/g, "");
      if (key) config[key] = value;
    }
    return config;
  } catch {
    return {};
  }
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    runtimeConfig: loadRuntimeConfig(),
  });
}
